args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Anna_Alojza_Ostrogska dbo:parent ?father .
  OPTIONAL {
    ?father rdfs:label ?fatherLabel .
    FILTER (langMatches(lang(?fatherLabel), "en") || langMatches(lang(?fatherLabel), "pl") || lang(?fatherLabel) = "")
  }
  FILTER regex(str(?fatherLabel), "Ostrogski", "i")
}

